const ICONS:Record<string,string>={line:'M3 17V7l6 4V7l6 4V4h6v16H3zm3-2h1m4 0h1m4 0h1',evidence:'M5 5h4v4H5zm10 0h4v4h-4zM10 16h4v4h-4zM7 9v4h5v3m5-7v4h-5',qualification:'M8 4h8v3H8zM6 6H4v15h16V6h-2M8 12l2 2 5-5m-7 9h8',investigation:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16m6-2 6 6M7 9h6m-3-3v6',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6h4',check:'M5 12l4 4L19 6',close:'m6 6 12 12M6 18 18 6',refresh:'M20 7v5h-5m4-5a8 8 0 1 0 1 9',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',chevron:'m9 5 7 7-7 7',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zm-5 10 3 3 7-7',user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0M4 22v-4a8 8 0 0 1 16 0v4',logout:'M9 3H3v18h6m6-15 6 6-6 6M8 12h13',menu:'M3 5h18M3 12h18M3 19h18',alert:'M12 3 2 21h20zm0 6v5m0 3v1',external:'M14 3h7v7m-9 2 9-9M10 3H3v18h18v-7'};
function Icon({name,size=18}:{name:string;size?:number}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={ICONS[name]||ICONS.evidence}/></svg>}
const STATUS_LABEL:Record<string,string>={ACCEPT:'Tests ready',HOLD:'More evidence needed',REJECT:'Condition failed',READY_FOR_QA:'Awaiting quality review',AUTHORIZED:'Approved within limit',HELD:'Paused',COMPLETED:'Finished',SATISFIED:'Met',VIOLATED:'Failed',UNKNOWN:'Needs information',VALID:'Eligible',INVALID:'Unusable',REVOKED:'Withdrawn'};
function Pill({value,children}:{value:string;children?:ReactNode}){return <span className={'pill '+(['ACCEPT','SATISFIED','VALID','PASS','VERIFIED','AUTHORIZED','ACTIVE','COMPLETE','SUPPORTED_IN_SIMULATION'].includes(value)?'good':['FAIL','REJECT','INVALID','REVOKED','INEFFECTIVE'].includes(value)?'bad':['HOLD','UNKNOWN','HELD','EXPIRED','PARTIAL','INCONCLUSIVE','READY_FOR_QA'].includes(value)?'warn':'neutral')}><span className="status-dot"/>{children||STATUS_LABEL[value]||pretty(value)}</span>}
function Empty({title,children}:{title:string;children:ReactNode}){return <div className="empty"><Icon name="evidence" size={28}/><h3>{title}</h3><p>{children}</p></div>}
const pages=TABS.map(t=>t.id);
function initialRoute(){const p=new URLSearchParams(location.search);return {page:[...pages,'start'].includes(location.pathname.split('/')[1])?location.pathname.split('/')[1]:'start',wid:p.get('workspace')||'',rid:p.get('run')||'',did:p.get('decision')||''}}

export default function App(){
 const [route,setRoute]=useState(initialRoute);const [actor,setActor]=useState<Actor|null>(null);const [checking,setChecking]=useState(true);
 const [workspaces,setWorkspaces]=useState<Workspace[]>([]);const [s,setS]=useState<Snapshot|null>(null);const [busy,setBusy]=useState(false);const [offline,setOffline]=useState(false);const [error,setError]=useState('');const [toast,setToast]=useState('');
 const [drawer,setDrawer]=useState<Entity|null>(null);const [modal,setModal]=useState<{op:string;payload:Record<string,any>;reason:string;inputText?:string}|null>(null);const [navOpen,setNavOpen]=useState(false);const [validation,setValidation]=useState<any>(null);const [lineTab,setLineTab]=useState('overview');
 const [earlier,setEarlier]=useState<Workspace[]|null>(null);
 const trigger=useRef<HTMLElement|null>(null);const dialog=useRef<HTMLDivElement>(null);const requests=useRef(0);
 const pendingCommand=useRef<{identity:string;key:string;revision:number}|null>(null);
 const navigate=useCallback((updates:Partial<ReturnType<typeof initialRoute>>)=>{const next={...route,...updates};const p=new URLSearchParams();if(next.wid)p.set('workspace',next.wid);if(next.rid)p.set('run',next.rid);if(next.did)p.set('decision',next.did);history.pushState({},'',`/${next.page}?${p}`);setRoute(next);setNavOpen(false);},[route]);
 useEffect(()=>{const f=()=>setRoute(initialRoute());window.addEventListener('popstate',f);return()=>window.removeEventListener('popstate',f)},[]);
 const load=useCallback(async()=>{if(!route.wid||!actor)return;const request=++requests.current;try{const params=new URLSearchParams();if(route.rid)params.set('run_id',route.rid);if(route.did)params.set('decision_id',route.did);const value=await api<Snapshot>(`/workspaces/${route.wid}/snapshot?${params}`);if(request!==requests.current)return;setS(value);setOffline(false);localStorage.setItem('qualityos-workspace',route.wid);return value}catch(e){if(request!==requests.current)return;if(e instanceof ApiError&&e.status===401)setActor(null);else if(e instanceof ApiError&&e.status===404){setS(null);setError(e.message)}else setOffline(true)}},[route.wid,route.rid,route.did,actor]);
 useEffect(()=>{api<{actor:Actor}>('/auth/me').then(x=>setActor(x.actor)).catch(()=>{}).finally(()=>setChecking(false))},[]);
 useEffect(()=>{if(actor){api<Workspace[]>('/workspaces').then(setWorkspaces).catch(()=>setOffline(true));load()}},[actor,load]);
 useEffect(()=>{if(!actor||!route.wid||route.did)return;const t=setInterval(()=>{if(document.hidden)return;api(`/workspaces/${route.wid}/changes?after_seq=${s?.workspace.cursor||0}`).then(x=>{setOffline(false);if(x.changed)load()}).catch(()=>setOffline(true))},1000);return()=>clearInterval(t)},[actor,route.wid,route.did,s?.workspace.cursor,load]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!modal&&!drawer)return;trigger.current=document.activeElement as HTMLElement;const focus=()=>dialog.current?.querySelector<HTMLElement>('input,select,button,[tabindex="0"]')?.focus();const t=setTimeout(focus,20);const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setDrawer(null)}if(e.key==='Tab'&&dialog.current){const list=[...dialog.current.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,textarea,a[href],[tabindex="0"]')];if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',key);return()=>{clearTimeout(t);document.removeEventListener('keydown',key);trigger.current?.focus()}},[!!modal,!!drawer]);
 const contextMatches=!!s&&s.workspace.id===route.wid&&(!route.rid||s.run.id===route.rid)&&s.historical===!!route.did&&(!route.did||s.decision.id===route.did);
 const writable=!!actor&&canWrite(actor)&&contextMatches&&!offline&&!s?.historical&&!busy;
 const allowed=(op:string)=>writable&&(!qaRequired(op)||actor?.role==='QUALITY_ENGINEER');
 const notifyError=async(e:unknown)=>{setError(e instanceof Error?e.message:'Request failed');if(e instanceof ApiError&&['STALE_CONTEXT','STALE_DECISION'].includes(e.code)){await load()}};
 const records=s?Object.values(s.records):[];
 const byKind=(kind:string)=>records.filter(x=>x.kind===kind);
 const currentStudies=s?byKind('study').filter(x=>s.decision.study_ids.includes(x.id)).sort((a,b)=>a.created_at.localeCompare(b.created_at)):[];
 const openStudies=currentStudies.filter(x=>!s?.test_sets?.find(t=>t.study_id===x.id)?.has_results);
 const lastStudy=openStudies.at(-1);
 const lastStudyStatus=s?.test_sets?.find(t=>t.study_id===lastStudy?.id);
 const latestMeasurement=s?[...s.decision.measurements].sort((a,b)=>(a.recorded_revision||0)-(b.recorded_revision||0)||a.occurred_at.localeCompare(b.occurred_at)).at(-1):undefined;
 const runIncidents=byKind('investigation').filter(x=>x.run_id===s?.run.id);
 const actions=byKind('action').filter(x=>x.run_id===s?.run.id);
 function open(op:string,extra:Record<string,any>={}){
  if(op==='measure')op='measure_batch';
  if(!s&&op!=='new_workspace')return;
  const run=s?.run;const rid=run?.id;const r=s?.records||{};
  const fresh=byKind('calibration').sort((a,b)=>a.valid_from.localeCompare(b.valid_from)).at(-1);
  const old=byKind('calibration').find(x=>x.id.endsWith('calibration-02-old'));
  const relevantFresh=byKind('calibration').filter(x=>x.instrument_id===old?.instrument_id).sort((a,b)=>a.valid_from.localeCompare(b.valid_from)).at(-1);
  const usable=byKind('calibration').find(c=>new Date(c.valid_from)<=new Date(s?.clock||'')&&new Date(s?.clock||'')<=new Date(c.valid_until)&&!byKind('revocation').some(v=>v.calibration_id===c.id&&new Date(v.effective_from)<=new Date(s!.clock)&&new Date(s!.clock)<=new Date(v.effective_until)));
  const payloads:Record<string,Record<string,any>>={
   new_workspace:{name:'My packaging experiment',scenario:'S1',guided:false,purpose:'USER_EXPERIMENT',setup:defaultSetup()},change_context:{run_id:rid,field:'closure_lot_id',value:byKind('lot').find(x=>x.id.endsWith('closure-c02'))?.id},open_study:{run_id:rid,...(actions.find(x=>x.status==='EXECUTED')?{action_id:actions.find(x=>x.status==='EXECUTED')!.id}:{})},
   measure_batch:{study_id:lastStudy?.id||'',calibration_id:usable?.id||'',values:[],unit:'N_m',half_width:'0.02',uncertainty_kind:'ENGINEERING_BOUND',basis:'Assumed error bound for user-chosen fictional readings'},
   measure:{study_id:lastStudy?.id||'',calibration_id:(relevantFresh||old||fresh)?.id||'',value:'1.00',unit:'N_m',half_width:'0.02',count:3,uncertainty_kind:'ENGINEERING_BOUND',basis:'Assumed engineering bound for this synthetic software demonstration'},
   functional:{study_id:lastStudy?.id||'',outcome:''},calibrate:{instrument_id:byKind('instrument').find(x=>x.id.endsWith('torque-02'))?.id,method_id:'synthetic-reference-v1',basis:'Assumed valid reference for the declared synthetic protocol'},
   advance:{hours:24},refresh_source:{run_id:rid,complete:true},investigate:{run_id:rid,title:'Problem observed in this experiment',problem_definition:`Current decision for ${r[run?.closure_lot_id]?.label||'these caps'} / ${r[run?.config_id]?.label||'this setup'}: ${s?.decision.recommendation}. ${s?.guidance.reason||'Describe the recorded result that needs explaining.'}`},
   hypothesis:{investigation_id:runIncidents.at(-1)?.id||'',statement:'',mechanism:'',supporting_ids:[],refuting_ids:[]},
   propose_action:{investigation_id:runIncidents.at(-1)?.id||'',config_id:byKind('config').find(x=>x.id.endsWith('capper-v2'))?.id,verification_plan:'Collect three fresh torque readings with a valid reference, then an independent leak result after 24 demonstration hours.'},
   approve_action:{action_id:actions.at(-1)?.id},execute_action:{action_id:actions.at(-1)?.id},assess_action:{action_id:actions.at(-1)?.id},
   resolve_hold:{run_id:rid,decision_id:s?.decision.id,fingerprint:s?.decision.applicability_fingerprint},authorize:{run_id:rid,decision_id:s?.decision.id,fingerprint:s?.decision.applicability_fingerprint,max_units:20,minutes:15},
   produce:{run_id:rid,units:5},complete_run:{run_id:rid},comment:{run_id:rid,text:''},
   revoke_calibration:{calibration_id:byKind('calibration').filter(x=>x.id!==old?.id).at(-1)?.id,effective_from:'2026-01-14T00:00:00Z',effective_until:s?.clock},
   disposition:{unit_ids:s?.impact.units.map(x=>x.id)||[],disposition:'HELD'},correct_evidence:{evidence_id:byKind('functional').at(-1)?.id,outcome:'INCONCLUSIVE'}
  };
  if(op==='investigate'&&runIncidents.length&&!extra.force){navigate({page:'investigation'});return}
  const cleanExtra={...extra};delete cleanExtra.force;
  setError('');setToast('');setModal({op,payload:{...payloads[op],...cleanExtra},reason:''});
 }
 async function submit(e:FormEvent){e.preventDefault();if(!modal||!actor)return;if(offline){setError('Reconnect to the local service before recording this action.');return}if(modal.op!=='new_workspace'&&!writable){setError('Review the current editable context before recording this action.');return}setBusy(true);setError('');try{
  if(modal.op==='new_workspace'){const result=await api('/demo/workspaces',{method:'POST',body:JSON.stringify(modal.payload)});setWorkspaces(await api('/workspaces'));setS(null);navigate({wid:result.workspace_id,rid:'',did:'',page:'line'});setToast('Experiment created with your selected inputs')}
  else if(s){const identity=JSON.stringify({wid:s.workspace.id,operation:modal.op,payload:modal.payload,reason:modal.reason});if(pendingCommand.current?.identity!==identity)pendingCommand.current={identity,key:crypto.randomUUID(),revision:s.workspace.revision};const pending=pendingCommand.current;const receipt=await command(s.workspace.id,pending.revision,modal.op,modal.payload,modal.reason,pending.key);pendingCommand.current=null;await load();setToast((receipt.replayed?'Recovered existing receipt · ':'Recorded · ')+pretty(modal.op))}
  setModal(null);
 }catch(e){if(e instanceof ApiError)pendingCommand.current=null;await notifyError(e)}finally{setBusy(false)}}
 function field(name:string,label:string,options?:{id:string;label:string}[],type='text',help?:string){if(!modal)return null;return <label className="field" key={name}><span>{label}</span>{options?<select name={name} value={modal.payload[name]??''} onChange={e=>setModal({...modal,payload:{...modal.payload,[name]:e.target.value}})} required>{options.length===0&&<option value="">No applicable records available</option>}{options.map(x=><option value={x.id} key={x.id}>{x.label}</option>)}</select>:type==='textarea'?<textarea name={name} placeholder={FIELD_HELP[name]?.example||''} value={modal.payload[name]??''} onChange={e=>setModal({...modal,payload:{...modal.payload,[name]:e.target.value}})} required rows={3}/>:<input name={name} type={type} placeholder={FIELD_HELP[name]?.example||''} value={modal.payload[name]??''} onChange={e=>setModal({...modal,payload:{...modal.payload,[name]:type==='number'?Number(e.target.value):e.target.value}})} required/>}{(help||FIELD_HELP[name]?.help)&&<small>{help||FIELD_HELP[name]?.help}</small>}</label>}
 function formFields(){if(!modal)return null;const kindOptions=(kind:string,filter=(x:Entity)=>true)=>byKind(kind).filter(filter).map(x=>({id:x.id,label:x.label||x.id}));switch(modal.op){
  case 'new_workspace':return <ExperimentBuilder value={modal.payload} onChange={payload=>setModal({...modal,payload})}/>;
  case 'change_context':return <>{field('field','Assignment',[{id:'closure_lot_id',label:'Cap batch'},{id:'bottle_lot_id',label:'Bottle batch'},{id:'config_id',label:'Machine setup'},{id:'lineage',label:'Traceability completeness'}])}{field('value','New value',modal.payload.field==='lineage'?[{id:'COMPLETE',label:'Complete'},{id:'PARTIAL',label:'Partial / conservative scope'}]:kindOptions(modal.payload.field==='config_id'?'config':'lot',x=>modal.payload.field==='config_id'||x.component===(modal.payload.field==='bottle_lot_id'?'BOTTLE':'CLOSURE')))}<p className="form-note">The app will check which saved tests apply to your chosen combination. C02 is not covered by the earlier example tests. C03 is explicitly covered. New batches do not inherit earlier approval simply because they look similar.</p></>;
  case 'measure_batch':return <>{field('study_id','Test set',openStudies.map(x=>({id:x.id,label:x.label||x.id})))}<label className="field"><span>Your fictional torque readings · N·m</span><textarea name="readings" required rows={2} value={modal.inputText??modal.payload.values.join(', ')} onChange={e=>{const inputText=e.target.value;setModal({...modal,inputText,payload:{...modal.payload,values:inputText.split(/[,\n]/).map(x=>x.trim()).filter(Boolean)}})}} placeholder="e.g. 0.98, 1.00, 1.02"/><small>One reading per fresh fictional specimen, separated by commas. You can enter 1–12 readings; the example protocol needs at least 3 eligible specimens to pass.</small></label><button type="button" className="text-button sample-readings" onClick={()=>setModal({...modal,inputText:'0.98, 1.00, 1.02',payload:{...modal.payload,values:['0.98','1.00','1.02']}})}>Use three example readings</button>{field('calibration_id','Measuring-tool reference',kindOptions('calibration'))}<p className="form-note">Example limits: 0.90–1.10 N·m. The assumed error bound is ±{modal.payload.half_width} N·m. These are demonstration inputs, not factory measurements.</p><details className="advanced-inputs"><summary>Adjust the assumed measurement error</summary>{field('half_width','Assumed error half-bound · N·m')}{field('uncertainty_kind','Type of error information',[{id:'ENGINEERING_BOUND',label:'Assumed engineering bound'},{id:'UNKNOWN',label:'Unknown / missing information'},{id:'EXPANDED_UNCERTAINTY',label:'Expanded uncertainty · unsupported by this example'}])}{field('basis','What this error assumption is based on',undefined,'textarea')}</details></>;
  case 'calibrate':return <>{field('instrument_id','Instrument',kindOptions('instrument'))}{field('method_id','Reference method')}{field('basis','Reference basis',undefined,'textarea')}<p className="form-note">Add an instrument reference validity begins at the replay clock. It cannot repair readings collected under an invalid earlier reference.</p></>;
  case 'functional':return <>{field('study_id','Scoped study',openStudies.map(x=>({id:x.id,label:x.label||x.id})))}{field('outcome','Independent functional observation',[{id:'',label:'Choose the fictional outcome you want to try'},{id:'INCONCLUSIVE',label:'Inconclusive · result does not settle the question'},{id:'FAIL',label:'Fail · supplied test observed a leak'},{id:'PASS',label:'Pass · supplied test observed no leak'}])}<p className="form-note">Supply the fictional observation you want to try. PASS means no leak was observed in that supplied test; FAIL means a leak was observed; INCONCLUSIVE leaves the question unresolved. The required 24 demonstration hours must have passed for every specimen.</p></>;
  case 'advance':return <>{field('hours','Advance demonstration time by hours',undefined,'number')}<p className="form-note">This changes logical scenario time. It does not represent instant physical testing, refresh a source heartbeat or renew a QA permission.</p></>;
  case 'refresh_source':return <p className="form-note">Explicitly record a complete, current synthetic source watermark for this run. This does not renew an expired permission.</p>;
  case 'investigate':return <>{field('title','Investigation title')}{field('problem_definition','Problem definition',undefined,'textarea')}</>;
  case 'hypothesis':return <>{field('investigation_id','Investigation',kindOptions('investigation',x=>x.run_id===s?.run.id))}{field('statement','Your possible explanation')}{field('mechanism','How could this cause the observed issue?',undefined,'textarea')}<label className="field"><span>Observations supporting this explanation</span><select multiple value={modal.payload.supporting_ids} onChange={e=>setModal({...modal,payload:{...modal.payload,supporting_ids:[...e.target.selectedOptions].map(x=>x.value)}})}>{records.filter(x=>['measurement','functional','revocation'].includes(x.kind)&&(x.kind==='revocation'||s!.decision.study_ids.includes(x.study_id))).map(x=><option key={x.id} value={x.id}>{x.label} · {x.id.slice(-6)}</option>)}</select></label><label className="field"><span>Observations challenging this explanation</span><select multiple value={modal.payload.refuting_ids} onChange={e=>setModal({...modal,payload:{...modal.payload,refuting_ids:[...e.target.selectedOptions].map(x=>x.value)}})}>{records.filter(x=>['measurement','functional','revocation'].includes(x.kind)&&(x.kind==='revocation'||s!.decision.study_ids.includes(x.study_id))).map(x=><option key={x.id} value={x.id}>{x.label} · {x.id.slice(-6)}</option>)}</select></label></>;
  case 'propose_action':return <>{field('investigation_id','Investigation',kindOptions('investigation',x=>x.run_id===s?.run.id))}{field('config_id','Proposed configuration',kindOptions('config'))}{field('verification_plan','Independent verification plan',undefined,'textarea')}</>;
  case 'authorize':return <><div className="review-scope"><Icon name="shield"/><div><strong>Authorize this simulation only</strong><p>Reviewing {s?.records[s.run.closure_lot_id]?.label} with {s?.records[s.run.config_id]?.label}. Approval covers only this combination and the limits below.</p></div></div><div className="form-grid">{field('max_units','Maximum units',undefined,'number')}{field('minutes','Permission duration · minutes',undefined,'number')}</div></>;
  case 'produce':return <>{field('units','Simulated units to create',undefined,'number')}<p className="form-note">Each unit retains its actual component/configuration assignments and permission. This command does not operate equipment.</p></>;
  case 'comment':return field('text','Review note',undefined,'textarea');
  case 'revoke_calibration':return <>{field('calibration_id','Reference to revoke',kindOptions('calibration'))}{field('effective_from','Effective interval start · ISO UTC')}{field('effective_until','Effective interval end · ISO UTC')}<p className="form-note">Current reassessment may change. Original decisions and observed history remain intact.</p></>;
  case 'correct_evidence':return <>{field('evidence_id','Result to correct',kindOptions('functional'))}{field('outcome','Corrected outcome',[{id:'INCONCLUSIVE',label:'Inconclusive'},{id:'FAIL',label:'Fail'},{id:'PASS',label:'Pass'}])}<p className="form-note">A new version supersedes the earlier result in current reassessment. Its original content remains visible.</p></>;
  case 'disposition':return <>{field('disposition','QA simulation disposition',[{id:'HELD',label:'Held'},{id:'ACCEPTED',label:'Accepted'},{id:'REJECTED',label:'Rejected'}])}<p className="form-note">Applies to {modal.payload.unit_ids.length} potentially affected simulated units. Potential impact is not proof of a defect.</p></>;
  default:{const selected=byKind('action').find(x=>x.id===modal.payload.action_id);return <div className="review-scope"><Icon name="shield"/><div><strong>{selected?'Selected change':'Selected production condition'}</strong><p>{selected?s?.records[selected.config_id]?.label:s?.records[s.run.closure_lot_id]?.label+' / '+s?.records[s.run.config_id]?.label}</p>{selected&&<p>{selected.verification_plan}</p>}</div></div>}

 }}
 if(checking)return <div className="boot"><div className="brand-symbol"/><span>Opening QualityOS</span></div>;
 if(!actor)return <Login onLogin={setActor}/>;
 const headerTitle=tabName(route.page);
 const holds=s?byKind('hold').filter(x=>x.run_id===s.run.id&&x.status==='ACTIVE'):[];
 const units=s?byKind('unit').filter(x=>x.run_id===s.run.id):[];
 const permits=s?byKind('permit').filter(x=>x.run_id===s.run.id):[];
 const livePermit=permits.find(x=>x.status==='ACTIVE'&&x.used_units<x.max_units);
 function startExperiment(preset='custom'){open('new_workspace',{name:preset==='approved'?'Approved setup comparison':preset==='new-caps'?'Untested cap experiment':'My packaging experiment',setup:defaultSetup(preset)})}
 function openExperiment(wid:string){setS(null);navigate({wid,rid:'',did:'',page:'line'})}
 async function showEarlier(){try{setEarlier(await api('/workspaces?include_earlier=true'))}catch(e){notifyError(e)}}
 async function keepExperiment(w:Workspace){try{await api(`/workspaces/${w.id}/organize`,{method:'POST',body:JSON.stringify({name:w.name,purpose:'USER_EXPERIMENT'})});setWorkspaces(await api('/workspaces'));setEarlier(await api('/workspaces?include_earlier=true'));if(s?.workspace.id===w.id)await load();setToast('Saved session added to your experiments')}catch(e){notifyError(e)}}
 async function exportReceipt(){if(!s)return;try{const data=await api(`/workspaces/${s.workspace.id}/export`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`qualityos-${s.run.label}-synthetic.json`;a.click();URL.revokeObjectURL(url);setToast('Synthetic evidence receipt exported')}catch(e){notifyError(e)}}
 async function evaluateCorpus(){setBusy(true);try{setValidation(await api('/validation/run',{method:'POST',body:'{}'}));setToast('Independent evaluation completed')}catch(e){notifyError(e)}finally{setBusy(false)}}
 return <div className="app-shell">
  <aside className={'sidebar '+(navOpen?'is-open':'')}><a className="brand" href="/start" onClick={e=>{e.preventDefault();navigate({page:'start'})}}><span className="brand-symbol"/>Quality<span>OS</span></a><div className="environment"><span className="tiny-dot"/><div><strong>Quality decision lab</strong><small>Fictional inputs · saved results</small></div><span className="env-mark">Q</span></div><button className={'sidebar-home '+(route.page==='start'?'active':'')} onClick={()=>navigate({page:'start'})}><Icon name="arrow" size={16}/>Getting started</button><div className="nav-label">EXPERIMENT TABS</div><nav aria-label="Primary workspace">{pages.map((page,index)=><button key={page} data-page={page} aria-current={route.page===page?'page':undefined} className={route.page===page?'active':''} onClick={()=>navigate({page})}><Icon name={page}/><span className="nav-caption"><strong>{TABS[index].label}</strong><small>{TABS[index].hint}</small></span></button>)}</nav><div className="sidebar-context"><div className="nav-label">SAVED EXPERIMENT</div><select aria-label="Selected experiment" value={route.wid} onChange={e=>{setS(null);navigate({wid:e.target.value,rid:'',did:''})}}><option value="">Choose an experiment</option>{s&&!workspaces.some(w=>w.id===s.workspace.id)&&<option value={s.workspace.id}>Earlier session: {s.workspace.name}</option>}{workspaces.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select><button className="sidebar-new" disabled={!canWrite(actor)&&actor.role!=='ADMIN'} onClick={()=>open('new_workspace')}><Icon name="plus" size={15}/>Create experiment</button></div><div className="sidebar-bottom"><div className="demo-mark"><Icon name="shield" size={15}/>SYNTHETIC DEMO</div><p>Inspectable decisions.<br/>Explicit evidence boundaries.</p><div className="profile"><span className="avatar">{actor.display_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><strong>{actor.display_name}</strong><small>{actor.role==='QUALITY_ENGINEER'?'Quality reviewer':pretty(actor.role)}</small></div><button title="Sign out" aria-label="Sign out" onClick={async()=>{await api('/auth/session',{method:'DELETE'});setActor(null);setS(null)}}><Icon name="logout" size={17}/></button></div></div></aside>
  <div className="main-shell"><header className="topbar"><button className="mobile-menu" aria-label="Toggle navigation" onClick={()=>setNavOpen(!navOpen)}><Icon name="menu"/></button><div className="breadcrumb"><button onClick={()=>navigate({page:'start'})}>Getting started</button><span>/</span><strong>{route.page==='start'?'What this product does':tabName(route.page)}</strong></div><div className={'connection '+(offline?'disconnected':'')}><span className="status-dot"/>{offline?'Connection lost · actions paused':'Local service connected'}</div><span className="top-avatar">{actor.display_name[0]}</span></header>
   <main>{route.page!=='start'&&<div className="page-heading"><div><div className="eyebrow">SAVED EXPERIMENT <span> / </span>{s?.run.label||'LOCAL SANDBOX'}</div><h1>{headerTitle}<span className="title-point">.</span></h1><p>{TABS.find(t=>t.id===route.page)?.hint}</p></div><div className="heading-actions">{s&&<button className="button ghost" onClick={exportReceipt}><Icon name="download"/>Export experiment</button>}<button className="button" disabled={!canWrite(actor)&&actor.role!=='ADMIN'} onClick={()=>open('new_workspace')}><Icon name="plus"/>New experiment</button></div></div>}
    {error&&!modal&&<div className="notice error" role="alert"><Icon name="alert"/>{error}<button aria-label="Dismiss error" onClick={()=>setError('')}><Icon name="close"/></button></div>}
    {offline&&<div className="notice error" role="alert"><Icon name="alert"/>The last snapshot may be stale. Mutating actions are paused until the service reconnects.<button className="text-button" onClick={load}>Retry</button></div>}
    {s&&!contextMatches&&<div className="notice context-loading" role="status">Loading the selected run and its evidence. Actions will be available when this view is up to date.</div>}
    {s?.historical&&<div className="notice history"><Icon name="clock"/>As known at event {s.decision.known_through_seq} · {date(s.clock)}. This view is read-only.<button className="text-button" onClick={()=>navigate({did:''})}>Return to current</button></div>}
    {route.page==='start'?<GettingStarted actor={actor} experiments={workspaces} earlier={earlier} onCreate={startExperiment} onOpen={openExperiment} onEarlier={showEarlier} onKeep={keepExperiment}/>:!s?<section className="card onboarding"><span className="eyebrow">BEFORE USING THIS TAB</span><h2>Create or open an experiment.</h2><p>An experiment saves the materials, machine setup, fictional test results and decisions you want to explore. Choose one from your saved experiments or configure a new one.</p><button className="button primary" disabled={!canWrite(actor)&&actor.role!=='ADMIN'} onClick={()=>startExperiment()}>Create experiment</button></section>:<>
     {s.workspace.purpose!=='USER_EXPERIMENT'&&<div className="legacy-session"><span>This is a preserved earlier session or development check. It is separate from your normal experiments.</span><button className="text-button" disabled={!canWrite(actor)&&actor.role!=='ADMIN'} onClick={()=>keepExperiment(s.workspace)}>Keep in my experiments</button></div>}
     <div className="run-context"><div className="run-selector"><span className="context-label">SELECTED RUN</span><select aria-label="Selected production run" value={s.run.id} onChange={e=>navigate({rid:e.target.value,did:''})}>{s.runs.map(r=><option key={r.id} value={r.id}>{r.label} · {r.line}</option>)}</select><small>Use the main run for your inputs; the second run is an independent comparison.</small></div><div className="context-separator"/><div><span className="context-label">PRODUCT</span><strong>{s.records[s.run.product_id]?.label}</strong><small>100 g · fictional packaging family</small></div><div className="context-clock"><span className="context-label"><Icon name="clock" size={12}/> DEMONSTRATION CLOCK</span><strong className="mono">{date(s.clock)}</strong><small>Scenario time · not elapsed physical testing</small></div><Pill value={s.run.state}/></div>
     <TabInstructions page={route.page}/>
     {route.page==='line'&&<><div className="tabbar"><button className={lineTab==='overview'?'active':''} onClick={()=>setLineTab('overview')}>Overview</button><button className={lineTab==='validation'?'active':''} onClick={async()=>{setLineTab('validation');setValidation(await api('/validation'))}}>Independent evaluation</button></div>{lineTab==='overview'?<>
      <div className="line-grid"><section className="card process-card"><div className="panel-heading"><div><span className="eyebrow">PROCESS READINESS</span><h2>Can sample production continue?</h2></div><span className="subtle-tag">{s.run.line}</span></div><ProcessRail s={s} units={units.length} permit={!!livePermit} onStage={page=>navigate({page})}/><div className="process-caption"><span className="status-dot"/>{s.decision.recommendation==='ACCEPT'?(livePermit?'QA permission is active for a bounded simulation.':'Evidence is ready. QA permission is a separate step.'):'Further simulated production is blocked pending scoped evidence.'}</div><div className="process-divider"/><div className="scope-heading"><h3>What this experiment is using</h3><button className="text-button" disabled={!allowed('change_context')} onClick={()=>open('change_context')}>Change an input <Icon name="arrow" size={15}/></button></div><table className="scope-table"><thead><tr><th>Component</th><th>Assigned identity</th></tr></thead><tbody>{[['Bottle batch','bottle_lot_id'],['Cap batch','closure_lot_id'],['Machine setup','config_id']].map(([label,key])=><tr key={key}><td>{label}</td><td><button className="record-link" onClick={()=>setDrawer(s.records[s.run[key]])}>{s.records[s.run[key]]?.label}<Icon name="external" size={13}/></button></td></tr>)}</tbody></table></section>
      <section className={'card decision-card decision-'+s.decision.recommendation.toLowerCase()}><div className="decision-top"><span className="eyebrow">DECISION BRIEF</span><Icon name="shield" size={22}/></div><Pill value={s.decision.recommendation}>{s.decision.recommendation==='ACCEPT'?'Evidence ready':s.decision.recommendation==='HOLD'?'More evidence required':'Condition rejected'}</Pill><h2>{s.decision.recommendation==='ACCEPT'?(holds.length?'Ready for hold resolution.':livePermit?'Ready to continue.':'Ready for QA review.'):s.decision.recommendation==='HOLD'?'More test evidence is needed.':'A recorded condition failed its checks.'}</h2><p>{s.guidance.reason}</p><div className="decision-stats"><div><span>Checks satisfied</span><strong>{s.decision.requirements.filter(x=>x.verdict==='SATISFIED').length}<small> / {s.decision.requirements.length}</small></strong></div><div><span>Active run holds</span><strong>{holds.length.toString().padStart(2,'0')}</strong></div></div><div className="next-action"><span className="eyebrow">NEXT ACTION</span><button className="button primary" disabled={busy||!contextMatches} onClick={()=>s.guidance.operation==='produce'?open('produce'):navigate({page:s.guidance.operation==='investigate'?'investigation':'qualification'})}>{s.guidance.operation==='produce'?'Record sample units':s.guidance.operation==='investigate'?'Open Investigate a problem':'Open Tests & approval'}<Icon name="arrow"/></button>{!allowed(s.guidance.operation)&&<small>{s.historical?'Return to the current view to act.':s.guidance.qa_required&&actor.role!=='QUALITY_ENGINEER'?'A quality engineer must review this step.':actor.role==='VIEWER'?'Read-only visitor access.':'Actions require a fresh connected context.'}</small>}</div><p className="decision-footnote">Evidence acceptance is not commercial product release.</p></section></div>
      <div className="support-grid"><section className="card"><div className="panel-heading"><div><span className="eyebrow">SAVED SAMPLE UNITS</span><h2>Recorded sample production</h2></div><Icon name="line"/></div><div className="production-number">{units.length.toString().padStart(2,'0')}<span>units recorded</span></div><div className="progress-track"><span style={{width:`${livePermit?Math.min(100,livePermit.used_units/livePermit.max_units*100):0}%`}}/></div><div className="progress-label"><span>{livePermit?`${livePermit.max_units-livePermit.used_units} units remaining on permission`:'No live permission with remaining budget'}</span><span>{livePermit?`${livePermit.used_units} / ${livePermit.max_units} used`:'No active budget'}</span></div><div className="inline-actions"><button className="button small" disabled={!allowed('produce')||!livePermit} onClick={()=>open('produce')}>Record sample units <Icon name="arrow" size={15}/></button><button className="text-button" disabled={!allowed('complete_run')||!units.length} onClick={()=>open('complete_run')}>Complete run</button></div><small className="muted">Each unit stores its exact material, configuration and permission lineage.</small></section><section className="card"><div className="panel-heading"><div><span className="eyebrow">CURRENT TEST STATUS</span><h2>Required checks</h2></div><button className="icon-button" aria-label="Open qualification checks" onClick={()=>navigate({page:'qualification'})}><Icon name="arrow"/></button></div><div className="check-list">{s.decision.requirements.map(q=><button key={q.type} onClick={()=>navigate({page:'qualification'})}><span className={'check-symbol '+q.verdict.toLowerCase()}>{q.verdict==='SATISFIED'?<Icon name="check" size={12}/>:q.verdict==='VIOLATED'?'!':'?'}</span><span>{REQUIREMENTS[q.type]||pretty(q.type)}</span><span className="check-word">{pretty(q.verdict)}</span></button>)}</div></section></div>
      <section className="card recent-card"><div className="panel-heading"><div><span className="eyebrow">SAVED ACTIVITY</span><h2>Recent activity</h2></div><button className="text-button" onClick={()=>navigate({page:'evidence'})}>View evidence history <Icon name="arrow" size={15}/></button></div><Activity s={s} onSelect={setDrawer} limit={4}/></section>
     </>:<Validation value={validation} busy={busy} allowed={actor.role==='QUALITY_ENGINEER'||actor.role==='ADMIN'} onRun={evaluateCorpus}/>}</>}
     {route.page==='evidence'&&<><div className="section-toolbar"><div><Pill value={s.historical?'AS_KNOWN':'CURRENT_REASSESSMENT'}/><span className="muted"> Relation does not establish causation</span></div><select aria-label="Historical decision" value={route.did} onChange={e=>navigate({did:e.target.value})}><option value="">Current reassessment</option>{s.decisions.map(d=><option key={d.id} value={d.id}>As known · event {d.cut} · {pretty(d.recommendation)}</option>)}</select></div><section className="card"><div className="panel-heading"><div><span className="eyebrow">SAVED CHOICES AND THEIR CONSEQUENCES</span><h2>What changed in this experiment?</h2></div></div><HistoryList s={s} onSelect={setDrawer}/></section><details className="advanced-records"><summary>Inspect the underlying record links</summary><EvidenceGraph s={s} onSelect={setDrawer}/></details><section className="card"><div className="panel-heading"><div><span className="eyebrow">TEMPORAL RECORD</span><h2>What was known, and when</h2></div><span className="subtle-tag">Three distinct times</span></div><Activity s={s} onSelect={setDrawer} limit={100}/></section><details className="card detail-table"><summary>Accessible relation table · {s.edges.length} recorded links</summary><div className="table-scroll"><table><thead><tr><th>From</th><th>Relation</th><th>To</th><th>Source event</th></tr></thead><tbody>{s.edges.map((e,i)=><tr key={i}><td><button className="record-link" onClick={()=>setDrawer(s.records[e.from_id])}>{s.records[e.from_id]?.label||e.from_id}</button></td><td className="mono">{e.relation}</td><td><button className="record-link" onClick={()=>setDrawer(s.records[e.to_id])}>{s.records[e.to_id]?.label||e.to_id}</button></td><td className="mono">{e.source_event_id}</td></tr>)}</tbody></table></div></details></>}
     {route.page==='qualification'&&<><TestChecklist s={s} onAction={open} allowed={allowed}/><div className="section-toolbar"><div><Pill value={s.decision.recommendation}/><span className="muted"> Illustrative test requirements for the selected combination</span></div><button className="button" disabled={!allowed('open_study')} onClick={()=>open('open_study')}><Icon name="plus"/>Start a test set</button></div><div className="qualification-grid"><section className="card requirements-panel"><div className="panel-heading"><div><span className="eyebrow">TEST REQUIREMENTS</span><h2>What the tests must establish</h2></div></div>{s.decision.requirements.map((q,i)=><div className="requirement" key={q.type}><div className="requirement-heading"><span className="requirement-index">0{i+1}</span><h3>{REQUIREMENTS[q.type]||pretty(q.type)}</h3><Pill value={q.verdict}/></div><p>{q.reason}</p><div className="evidence-chips">{q.evidence_refs.slice(0,3).map(id=><button key={id} onClick={()=>setDrawer(s.records[id])}>{s.records[id]?.label||id}<Icon name="external" size={11}/></button>)}{q.evidence_refs.length>3&&<span>+{q.evidence_refs.length-3} records</span>}</div>{q.verdict!=='SATISFIED'&&<small className="required-next">Next: {q.next_action}</small>}</div>)}</section><div className="stack"><section className="card"><div className="panel-heading"><div><span className="eyebrow">MEASURING-TOOL CHECK</span><h2>Can these torque readings be used?</h2></div></div>{s.decision.measurements.length?<Interval measurement={latestMeasurement!} onSelect={setDrawer}/>:<Empty title="No applicable observations">Record new observations for this exact scope. Old qualification remains in history.</Empty>}<div className="inline-actions"><button className="button small" disabled={!allowed('measure')||!lastStudy} onClick={()=>open('measure')}>Enter torque readings</button><button className="text-button" disabled={!allowed('calibrate')} onClick={()=>open('calibrate')}>Add an instrument reference</button></div><details className="observations"><summary>All {s.decision.measurements.length} applicable observations</summary>{s.decision.measurements.map(m=><button key={m.id} onClick={()=>setDrawer(m)}><span className="mono">{m.value} {m.unit}</span><Pill value={m.reliability.verdict}/></button>)}</details></section><section className="card functional-card"><span className="eyebrow">INDEPENDENT PACKAGE TEST</span><h2>Enter the separate leak-test result.</h2><p>Enter your own fictional leak-test result after the example waiting period. Torque readings do not determine this outcome. Advancing demonstration time represents the wait without physically performing a test.</p><p className="test-time-status">{lastStudyStatus?.specimens?`${lastStudyStatus.specimens} specimen readings in the fresh set. ${Math.ceil(lastStudyStatus.wait_hours_remaining||0)} demonstration hours remain before a leak result can be recorded.`:'Start a test set and enter readings first. The example wait begins from those observations.'}</p><div className="dwell-visual"><Icon name="clock" size={26}/><strong>24<span>replay hours</span></strong><div className="dwell-lines"><i/><i/><i/><i/><i/><i/></div></div>{lastStudy&&<small className="muted">Study started {date(lastStudy.condition_start)}</small>}<div className="inline-actions"><button className="button small" disabled={!allowed('functional')||!lastStudy||!lastStudyStatus?.specimens||!!lastStudyStatus.wait_hours_remaining} onClick={()=>open('functional')}>Choose leak-test result</button><button className="text-button" disabled={!allowed('advance')} onClick={()=>open('advance')}>Advance demonstration time <Icon name="clock" size={14}/></button></div><button className="text-button" disabled={!allowed('refresh_source')} onClick={()=>open('refresh_source')}>Confirm current records</button></section></div></div><section className="card qa-panel"><div className="qa-icon"><Icon name="shield" size={26}/></div><div><span className="eyebrow">QUALITY REVIEWER APPROVAL</span><h2>Ready tests still need a review decision.</h2><p>Review the current snapshot, resolve any scoped hold, then issue bounded permission for the simulation.</p><small className="muted">Review the current test checklist before granting permission.</small></div><div className="qa-actions"><button className="button" disabled={!allowed('resolve_hold')||s.decision.recommendation!=='ACCEPT'||!holds.length} onClick={()=>open('resolve_hold')}>Resolve recorded pause</button><button className="button primary" disabled={!allowed('authorize')||s.decision.recommendation!=='ACCEPT'||!!holds.length} onClick={()=>open('authorize')}>Approve sample production <Icon name="arrow"/></button>{actor.role!=='QUALITY_ENGINEER'&&<small>Quality engineer authorization required</small>}</div></section></>}
     {route.page==='investigation'&&<><div className="investigation-banner"><div><span className="eyebrow">POTENTIAL IMPACT</span><h2>{s.impact.units.length.toString().padStart(2,'0')}<span>simulated units potentially affected</span></h2><p>{s.impact.reason}. Held does not mean defective or scrapped.</p></div><Pill value={s.impact.certainty}/><button className="button" disabled={!allowed('disposition')||!s.impact.units.length} onClick={()=>open('disposition')}>Record a handling decision</button></div><div className="section-toolbar"><h2>Describe the problem and compare a change</h2><div className="inline-actions"><button className="button primary" disabled={!allowed('investigate')} onClick={()=>open('investigate',{force:true})}><Icon name="plus"/>Describe a problem</button></div></div>{!runIncidents.length?<section className="card"><Empty title="No investigation for this run">Open a scoped investigation to retain competing explanations and record an approved, independently verified action.</Empty></section>:runIncidents.map(incident=><section key={incident.id} className="card investigation-card"><div className="panel-heading"><div><span className="eyebrow">SCOPED INVESTIGATION</span><h2>{incident.label}</h2><p>{incident.problem_definition}</p></div><Pill value={incident.status}/></div><div className="subsection-heading"><h3>Possible explanations to test</h3><button className="text-button" disabled={!allowed('hypothesis')} onClick={()=>open('hypothesis',{investigation_id:incident.id})}><Icon name="plus" size={14}/>Add a possible explanation</button></div>{byKind('hypothesis').filter(x=>x.investigation_id===incident.id).map(h=><div className="hypothesis" key={h.id}><div><h3>{h.statement}</h3><p>{h.mechanism}</p><small>Supporting: {h.supporting_ids.length} · Refuting: {h.refuting_ids.length} · association does not establish cause</small></div><button className="record-link" onClick={()=>setDrawer(h)}>Under test <Icon name="external" size={13}/></button></div>)}{!byKind('hypothesis').some(x=>x.investigation_id===incident.id)&&<p className="muted">No hypothesis recorded. Consider material scope, reference validity, application conditions and incomplete test conditions.</p>}<div className="subsection-heading"><h3>Change and verification progress</h3><button className="text-button" disabled={!allowed('propose_action')} onClick={()=>open('propose_action',{investigation_id:incident.id})}><Icon name="plus" size={14}/>Plan a change</button></div>{actions.filter(a=>a.investigation_id===incident.id).map(a=><div className="action-card" key={a.id}><div className="action-head"><button className="record-link" onClick={()=>setDrawer(a)}>{a.label}<Icon name="external" size={13}/></button><Pill value={a.status}/></div><div className="lifecycle">{['PROPOSED','APPROVED','EXECUTED','VERIFYING','VERIFIED'].map((stage,i)=><div className={['PROPOSED','APPROVED','EXECUTED','VERIFYING','VERIFIED'].indexOf(a.status)>=i?'done':''} key={stage}><span>{i+1}</span><small>{pretty(stage)}</small></div>)}</div><p>{a.verification_plan}</p><div className="inline-actions">{a.status==='PROPOSED'&&<button className="button primary small" disabled={!allowed('approve_action')} onClick={()=>open('approve_action',{action_id:a.id})}>Approve the change plan</button>}{a.status==='APPROVED'&&<button className="button primary small" disabled={!allowed('execute_action')} onClick={()=>open('execute_action',{action_id:a.id})}>Apply the approved setup</button>}{a.status==='EXECUTED'&&<button className="button primary small" disabled={!allowed('open_study')} onClick={()=>open('open_study',{run_id:s.run.id,action_id:a.id})}>Start a new verification set</button>}{a.status==='VERIFYING'&&<><button className="button small" onClick={()=>navigate({page:'qualification'})}>Complete verification <Icon name="arrow" size={14}/></button><button className="button primary small" disabled={!allowed('assess_action')||s.decision.recommendation!=='ACCEPT'} onClick={()=>open('assess_action',{action_id:a.id})}>Review the new verification</button></>}{a.status==='VERIFIED'&&<span className="effectiveness"><Icon name="check" size={17}/>Supported within this simulation · not a physical causal finding</span>}</div></div>)}</section>)}<section className="card"><div className="panel-heading"><div><span className="eyebrow">SAVED SAMPLES AND THEIR TEST RECORDS</span><h2>Which samples used which evidence?</h2></div></div>{units.length?<div className="table-scroll"><table><thead><tr><th>Unit</th><th>Closure / configuration</th><th>Produced at</th><th>Evidence</th><th>Disposition</th></tr></thead><tbody>{units.map(u=><tr key={u.id}><td><button className="record-link" onClick={()=>setDrawer(u)}>{u.label}</button></td><td>{s.records[u.scope.closure_lot_id]?.label}<small className="cell-small">{s.records[u.scope.config_id]?.label}</small></td><td className="mono">{date(u.produced_at)}</td><td>{u.evidence_ids.length} references</td><td>{byKind('disposition').filter(d=>d.unit_id===u.id).at(-1)?.disposition||'Unassessed'}</td></tr>)}</tbody></table></div>:<p className="muted">No simulated units have been committed. There is no manufactured impact count.</p>}</section></>}
     {route.page==='investigation'&&<details className="advanced-records"><summary>Advanced: simulate a later discovery or correct a test result</summary><p className="muted">Use these controls when you want to explore how later information affects saved evidence and sample units. Earlier decisions remain visible.</p><div className="inline-actions"><button className="button" disabled={!allowed('revoke_calibration')} onClick={()=>open('revoke_calibration')}>Withdraw a past reference</button><button className="button" disabled={!allowed('correct_evidence')||!byKind('functional').length} onClick={()=>open('correct_evidence')}>Correct a saved leak result</button></div></details>}
     <Glossary/>
     <footer className="workspace-footer"><span><span className="tiny-dot"/>Fictional-data experiment · no live equipment connection</span><span className="mono">EVENT {s.workspace.cursor} / REV {s.workspace.revision}</span></footer>
    </>}
   </main></div>
  {toast&&!modal&&!drawer&&<div className="toast" role="status"><Icon name="check"/>{toast}</div>}
  {(modal||drawer)&&<div className={'overlay '+(drawer&&!modal?'drawer-overlay':'')} onMouseDown={e=>{if(e.target===e.currentTarget){setModal(null);setDrawer(null)}}}><div className={modal?'modal':'drawer'} role="dialog" aria-modal="true" aria-labelledby="dialog-title" ref={dialog}>
   {modal?<form onSubmit={submit}><div className="dialog-heading"><div><span className="eyebrow">{qaRequired(modal.op)?'QUALITY REVIEW':'YOUR CHOSEN ACTION'}</span><h2 id="dialog-title">{ACTIONS[modal.op]?.title||pretty(modal.op)}</h2></div><button type="button" className="icon-button" aria-label="Close dialog" onClick={()=>setModal(null)}><Icon name="close"/></button></div><div className="dialog-body">{error&&<div className="notice error" role="alert">{error}</div>}<ActionExplanation operation={modal.op}/>{formFields()}{modal.op!=='new_workspace'&&modal.op!=='comment'&&(REQUIRED_NOTES.includes(modal.op)?<label className="field review-note"><span>{NOTE_LABEL[modal.op]||'Explain this decision'} · required</span><small>Leave a short explanation for someone reviewing this record later. Describe your review or intended experiment; do not claim physical testing.</small><textarea name="reason" rows={3} value={modal.reason} onChange={e=>setModal({...modal,reason:e.target.value})} required minLength={5} placeholder={ACTIONS[modal.op]?.example||'State what you reviewed and why you chose this action.'}/>{ACTIONS[modal.op]?.example&&<button type="button" className="text-button" onClick={()=>setModal({...modal,reason:ACTIONS[modal.op].example!})}>Use this example note (you can edit it)</button>}</label>:<details className="optional-note"><summary>Add an optional note</summary><label className="field"><span>Anything a later reader should know?</span><textarea name="reason" value={modal.reason} onChange={e=>setModal({...modal,reason:e.target.value})} rows={2}/></label></details>)}</div><div className="dialog-footer"><span><span className="status-dot"/>FICTIONAL TEST DATA</span><button type="button" className="button" onClick={()=>setModal(null)}>Cancel</button><button className="button primary" disabled={busy||offline||(modal.op!=='new_workspace'&&!writable)}>{busy?'Recording…':ACTIONS[modal.op]?.button||'Save action'}<Icon name="arrow" size={15}/></button></div></form>:drawer&&<><div className="dialog-heading"><div><span className="eyebrow">EVIDENCE RECORD</span><h2 id="dialog-title">{drawer.label||pretty(drawer.kind||drawer.type||'record')}</h2></div><button className="icon-button" aria-label="Close evidence drawer" onClick={()=>setDrawer(null)}><Icon name="close"/></button></div><div className="drawer-body"><span className="subtle-tag">SYNTHETIC</span><p className="mono drawer-id">{drawer.id}</p>{Object.entries(drawer).filter(([k])=>!['id','label','provenance'].includes(k)).map(([key,value])=><div className="record-field" key={key}><span>{pretty(key)}</span>{typeof value==='string'&&s?.records[value]?<button className="record-link" onClick={()=>setDrawer(s.records[value])}>{s.records[value].label||value}<Icon name="external" size={12}/></button>:<pre>{typeof value==='object'?JSON.stringify(value,null,2):String(value)}</pre>}</div>)}<p className="form-note">This is a persisted source or audit record. A provenance relation does not itself establish causation, commercial release or physical performance.</p></div></>}
  </div></div>}
 </div>
}

function Login({onLogin}:{onLogin:(actor:Actor)=>void}){const [username,setUsername]=useState('qa'),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);try{const result=await api('/auth/session',{method:'POST',body:JSON.stringify({username,password})});onLogin(result.actor)}catch(e){setError(e instanceof Error?e.message:'Unable to connect')}finally{setBusy(false)}}return <div className="login-page"><div className="login-story"><a className="brand" href="/start"><span className="brand-symbol"/>Quality<span>OS</span></a><div className="login-illustration"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="proof-card"><Icon name="shield" size={46}/><span>APPLICABLE PROOF</span><div/><div/><div/></div><span className="orbit-node node-one"><Icon name="evidence" size={22}/></span><span className="orbit-node node-two"><Icon name="qualification" size={22}/></span></div><h1>A factory makes product.<br/>What justifies continuing?</h1><p>Choose fictional production inputs and test data, then inspect the quality decision those records support.</p><span className="demo-mark"><Icon name="shield" size={15}/>LOCAL SYNTHETIC PROTOTYPE</span></div><div className="login-form-wrap"><form onSubmit={submit} className="login-form"><span className="eyebrow">YOUR QUALITY WORKSPACE</span><h2>Explore a quality decision.</h2><p>Sign in to create a saved experiment, choose its inputs and test results, and review the decision.</p>{error&&<div className="notice error" role="alert">{error}</div>}<label className="field"><span>Username</span><input autoComplete="username" name="username" value={username} onChange={e=>setUsername(e.target.value)} required/></label><label className="field"><span>Password</span><input type="password" autoComplete="current-password" name="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><button className="button primary login-submit" disabled={busy}>{busy?'Signing in…':'Open workspace'}<Icon name="arrow"/></button><details className="login-help"><summary>First local sign-in?</summary><p>Setup generates private credentials on this device in <code>qualityos/var/local-credentials.json</code>. Use the QA account for the quality-review actions in the demonstration, or the operator/viewer account to inspect role restrictions.</p></details><div className="login-security"><Icon name="shield" size={16}/>Your role determines which actions you can review.</div></form></div></div>}

function ProcessRail({s,units,permit,onStage}:{s:Snapshot;units:number;permit:boolean;onStage:(p:string)=>void}){const ready=s.decision.recommendation==='ACCEPT';return <div className="process-rail"><div className="rail-line"/><button className="rail-stage" onClick={()=>onStage('evidence')}><div className="stage-drawing components-drawing"><svg viewBox="0 0 84 90" aria-hidden="true"><path d="M17 23h23v7c0 5 7 7 7 13v38H10V43c0-6 7-8 7-13Z"/><path d="M18 16h21v8H18zM13 50h31v21H13zM58 22h18v16H58zM60 39h14v35H60z"/><path className="bottle-label" d="M22 58h15m-15 6h10"/></svg></div><span className="rail-number">01</span><strong>Components</strong><small>Exact lot identity</small><Pill value="COMPLETE">Assigned</Pill></button><button className="rail-stage" onClick={()=>onStage('qualification')}><div className={'stage-drawing '+(ready?'ready':'waiting')}><Icon name="qualification" size={40}/></div><span className="rail-number">02</span><strong>Qualification</strong><small>Scope + reference + test</small><Pill value={ready?'ACCEPT':s.decision.recommendation}>{ready?'Verified':'Needs review'}</Pill></button><button className="rail-stage" onClick={()=>onStage('qualification')}><div className={'stage-drawing '+(permit?'ready':'waiting')}><Icon name="shield" size={40}/></div><span className="rail-number">03</span><strong>Permission</strong><small>Bounded QA authorization</small><Pill value={permit?'ACTIVE':'UNKNOWN'}>{permit?'Authorized':'Awaiting QA'}</Pill></button><button className="rail-stage" onClick={()=>onStage('investigation')}><div className="stage-drawing output-drawing"><svg viewBox="0 0 84 90" aria-hidden="true">{[15,35,55].map((x,i)=><g key={x} opacity={units>i?'1':'.25'}><path d={`M${x} 29h12v7c0 3 4 6 4 9v30H${x-4}V45c0-3 4-6 4-9Z`}/><path d={`M${x} 22h12v7H${x}z`}/></g>)}<path d="M5 82h74"/></svg></div><span className="rail-number">04</span><strong>Simulated units</strong><small>Actual committed records</small><Pill value={units?'COMPLETE':'DRAFT'}>{units?`${units} recorded`:'Not started'}</Pill></button></div>}

function Activity({s,onSelect,limit}:{s:Snapshot;onSelect:(e:Entity)=>void;limit:number}){return <div className="activity">{s.events.slice(0,limit).map((event,i)=><button key={event.id} className="activity-row" onClick={()=>onSelect({...event,kind:'audit_event',label:pretty(event.type)})}><span className={'activity-marker '+(i===0?'latest':'')}><Icon name={event.type.includes('MEASURE')?'qualification':event.type.includes('ACTION')?'investigation':event.type.includes('PRODUCE')?'line':'evidence'} size={15}/></span><div><strong>{pretty(event.type)}</strong><small>Occurred {date(event.occurred_at)}<span> · </span>Available {date(event.available_at)}</small></div><span className="activity-receipt"><span className="mono">#{event.seq}</span><small>Received {date(event.recorded_at)}</small></span><Icon name="chevron" size={14}/></button>)}</div>}

function Interval({measurement:m,onSelect}:{measurement:Entity;onSelect:(e:Entity)=>void}){const valid=m.reliability?.verdict==='VALID';const interval=m.interval?.map(Number);const x=(n:number)=>Math.max(18,Math.min(342,18+(n-.75)/.5*324));return <div className="interval-view"><div className="reading"><strong>{m.value}<span>N·m</span></strong><Pill value={m.reliability?.verdict||'UNKNOWN'}/></div><svg viewBox="0 0 360 96" role="img" aria-label={valid?`Declared interval ${m.interval?.join(' to ')} N meters; illustrative tolerance 0.90 to 1.10`:'Observation has no eligible interval because reliability is invalid or unknown'}><rect x={x(.9)} y="22" width={x(1.1)-x(.9)} height="38" rx="3" fill="#e8f0e9"/><line x1="18" y1="60" x2="342" y2="60" stroke="#bcc8bf"/>{[.8,.9,1,1.1,1.2].map(v=><g key={v}><line x1={x(v)} y1="60" x2={x(v)} y2="65" stroke="#87968c"/><text x={x(v)} y="83" textAnchor="middle">{v.toFixed(2)}</text></g>)}{valid&&interval&&<><line x1={x(interval[0])} y1="40" x2={x(interval[1])} y2="40" stroke={m.conformance==='VIOLATED'?'#a3362e':'#255b45'} strokeWidth="5"/><circle cx={x(Number(m.value))} cy="40" r="6" fill="#255b45"/></>}{!valid&&<text x="180" y="44" textAnchor="middle">No eligible measurement interval</text>}</svg><div className="interval-meta"><span>Illustrative torque tolerance</span><strong className="mono">0.90–1.10 N·m</strong></div><p>{m.reliability?.reasons?.map(pretty).join(' · ')}</p><button className="text-button" onClick={()=>onSelect(m)}>Inspect reference and raw record <Icon name="external" size={13}/></button><small className="muted">Assumed engineering bound · not calibrated factory uncertainty.</small></div>}

function EvidenceGraph({s,onSelect}:{s:Snapshot;onSelect:(e:Entity)=>void}){const [expanded,setExpanded]=useState(false);const layers=[['lot','config','product'],['run','study'],['instrument','calibration','measurement','functional'],['hold','permit','action','revocation']];const max=expanded?7:4;const focus=new Set([s.run.id,...Object.values(s.decision.scope),...s.decision.evidence_refs,...s.decision.measurements.map(x=>x.id)]);const dependency=new Set(s.decision.measurements.flatMap(x=>[x.calibration_id,x.instrument_id]));const rank=(x:Entity)=>focus.has(x.id)?0:dependency.has(x.id)?1:2;const nodes=layers.flatMap((kinds,col)=>Object.values(s.records).filter(x=>kinds.includes(x.kind)).filter(x=>x.kind!=='run'||x.id===s.run.id).sort((a,b)=>rank(a)-rank(b)).slice(0,max).map((e,row)=>({e,x:30+col*238,y:55+row*74})));const map=new Map(nodes.map(n=>[n.e.id,n]));const links=s.edges.filter(e=>map.has(e.from_id)&&map.has(e.to_id)).filter((e,i,all)=>all.findIndex(x=>x.from_id===e.from_id&&x.to_id===e.to_id&&x.relation===e.relation)===i);return <section className="card graph-card"><div className="panel-heading"><div><span className="eyebrow">BOUNDED EVIDENCE GRAPH</span><h2>One decision. A traceable foundation.</h2></div><button className="button small" onClick={()=>setExpanded(!expanded)}>{expanded?'Compact view':'Expand records'}</button></div><div className="graph-columns"><span>COMPONENT / CONFIG</span><span>RUN / QUALIFICATION</span><span>MEASUREMENT / PROOF</span><span>WORKFLOW / PERMISSION</span></div><div className="graph-scroll"><svg className="evidence-graph" viewBox={`0 0 970 ${expanded?610:375}`} role="group" aria-label="Evidence dependency graph. A complete relation table follows the timeline."><defs><pattern id="dots" x="0" y="0" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="#dce2da"/></pattern></defs><rect width="970" height="100%" fill="url(#dots)"/>{links.map((l,i)=>{const a=map.get(l.from_id)!,b=map.get(l.to_id)!;return <path key={i} d={`M${a.x+96},${a.y+23} C${a.x+190},${a.y+23} ${b.x-65},${b.y+23} ${b.x},${b.y+23}`} fill="none" stroke="#b5c5b7" strokeWidth="1.3"/>})}{nodes.map(({e,x,y})=><g key={e.id} className="graph-node" role="button" tabIndex={0} aria-label={`Inspect ${e.label||e.kind}`} transform={`translate(${x},${y})`} onClick={()=>onSelect(e)} onKeyDown={event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();onSelect(e)}}}><rect width="202" height="51" rx="5" fill="#fff" stroke={e.id===s.run.id?'#255b45':'#cbd5cc'} strokeWidth={e.id===s.run.id?2:1}/><rect width="4" height="29" y="11" rx="2" fill={['hold','revocation'].includes(e.kind)?'#b8842b':'#53755e'}/><text x="14" y="18" className="graph-kind">{pretty(e.kind).toUpperCase()}</text><text x="14" y="37">{(e.label||e.id).slice(0,27)}</text><circle cx="188" cy="15" r="3" fill="#a1b3a4"/></g>)}</svg></div><div className="graph-legend"><span><i/>Recorded dependency</span><span><i className="outlined"/>Current selected run</span><span>{nodes.length} visible records · complete links in the table</span></div></section>}

function Validation({value,busy,allowed,onRun}:{value:any;busy:boolean;allowed:boolean;onRun:()=>void}){return <section className="card"><div className="panel-heading"><div><span className="eyebrow">INDEPENDENT SYNTHETIC CORPUS</span><h2>Correctness before claims.</h2></div><button className="button primary" disabled={!allowed||busy} onClick={onRun}>{busy?'Evaluating…':'Run independent evaluation'}<Icon name="arrow"/></button></div>{value?.status==='COMPLETED'?<><div className="evaluation-summary"><div><strong>{value.passed}<span>/{value.total}</span></strong><p>declared cases matched</p></div><div><Pill value={value.passed===value.total?'PASS':'FAIL'}/><p>{value.corpus_version}</p><small className="mono">{value.corpus_sha256.slice(0,20)}</small></div><div><strong>{value.latency_ms.p95}<span>ms</span></strong><p>pure policy p95 · this corpus</p></div></div><div className="table-scroll"><table><thead><tr><th>Policy / baseline</th><th>Matches</th><th>Boundary</th></tr></thead><tbody>{value.policies.map((p:any)=><tr key={p.name}><td>{p.name}</td><td className="mono">{p.matches}/{value.total}</td><td>{p.name.includes('reference')?'Parity retained; not a tested commercial MES':'Same declared cases and information cuts'}</td></tr>)}</tbody></table></div><details className="corpus-cases"><summary>Inspect all case outcomes</summary><div className="table-scroll"><table><thead><tr><th>Case</th><th>Expected</th><th>QualityOS</th><th>Reference</th></tr></thead><tbody>{value.cases.map((c:any)=><tr key={c.id}><td className="mono">{c.id}</td><td>{c.expected}</td><td><Pill value={c.actual}/></td><td>{c.reference}</td></tr>)}</tbody></table></div></details><div className="form-note">{value.limits.map((x:string)=><p key={x}>{x}</p>)}</div></>:<Empty title="Evaluation not run">Run the independent corpus to record actual policy outcomes. No passing count is seeded into this workspace.</Empty>}</section>}
